void MOD_mkTb::vcd_prims(tVCDDumpType dt, MOD_mkTb &backing)
{
  INST_cyc.dump_VCD(dt, backing.INST_cyc);
  INST_dbgRst.dump_VCD(dt, backing.INST_dbgRst);
  INST_dclk.dump_VCD(dt, backing.INST_dclk);
  INST_dut_cdc_haltB.dump_VCD(dt, backing.INST_dut_cdc_haltB);
  INST_dut_cdc_reqF.dump_VCD(dt, backing.INST_dut_cdc_reqF);
  INST_dut_cdc_respF.dump_VCD(dt, backing.INST_dut_cdc_respF);
  INST_dut_dbg_cur.dump_VCD(dt, backing.INST_dut_dbg_cur);
  INST_dut_dbg_st.dump_VCD(dt, backing.INST_dut_dbg_st);
  INST_dut_rdOwner.dump_VCD(dt, backing.INST_dut_rdOwner);
  INST_dut_wrOwner.dump_VCD(dt, backing.INST_dut_wrOwner);
  INST_fails.dump_VCD(dt, backing.INST_fails);
  INST_fsm_abort.dump_VCD(dt, backing.INST_fsm_abort);
  INST_fsm_jj_1_delay_count.dump_VCD(dt, backing.INST_fsm_jj_1_delay_count);
  INST_fsm_jj_delay_count.dump_VCD(dt, backing.INST_fsm_jj_delay_count);
  INST_fsm_start_reg.dump_VCD(dt, backing.INST_fsm_start_reg);
  INST_fsm_start_reg_1.dump_VCD(dt, backing.INST_fsm_start_reg_1);
  INST_fsm_start_reg_2.dump_VCD(dt, backing.INST_fsm_start_reg_2);
  INST_fsm_start_wire.dump_VCD(dt, backing.INST_fsm_start_wire);
  INST_fsm_state_can_overlap.dump_VCD(dt, backing.INST_fsm_state_can_overlap);
  INST_fsm_state_fired.dump_VCD(dt, backing.INST_fsm_state_fired);
  INST_fsm_state_fired_1.dump_VCD(dt, backing.INST_fsm_state_fired_1);
  INST_fsm_state_mkFSMstate.dump_VCD(dt, backing.INST_fsm_state_mkFSMstate);
  INST_fsm_state_overlap_pw.dump_VCD(dt, backing.INST_fsm_state_overlap_pw);
  INST_fsm_state_set_pw.dump_VCD(dt, backing.INST_fsm_state_set_pw);
  INST_li.dump_VCD(dt, backing.INST_li);
  INST_loaded.dump_VCD(dt, backing.INST_loaded);
  INST_loadedSync.dump_VCD(dt, backing.INST_loadedSync);
  INST_rdVal.dump_VCD(dt, backing.INST_rdVal);
  INST_started.dump_VCD(dt, backing.INST_started);
}

void MOD_mkTb::vcd_submodules(tVCDDumpType dt, unsigned int levels, MOD_mkTb &backing)
{
  INST_dut_core.dump_VCD(dt, levels, backing.INST_dut_core);
  INST_dut_dbg_dmem.dump_VCD(dt, levels, backing.INST_dut_dbg_dmem);
  INST_dut_mem.dump_VCD(dt, levels, backing.INST_dut_mem);
}
